[IO.File]::WriteAllText((Join-Path $PWD 'wait-for-log.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Waits, at most ten seconds, until the log holds <count> lines with <text>, then prints them`n# without their exchange numbers. Exit 1 if they never come.`n# Usage: sh wait-for-log.sh <text> <count> <log file>`ntries=0`nuntil [ `"`$(grep -c -F -- `"`$1`" `"`$3`")`" -ge `"`$2`" ]; do`n  tries=`$((tries + 1))`n  [ `"`$tries`" -ge 10 ] && exit 1`n  sleep 1`ndone`ngrep -F -- `"`$1`" `"`$3`" | sed 's/^#[0-9]* //'`n")
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--mail-domain', 'example.com', '--mail-domain', 'example.org', '--mailbox', 'billing@example.com:billpass', '--mailbox', 'ann@example.com:annpass', '--mailbox', 'sales@example.org:salespass', 'smtp://127.0.0.1:8080/', 'pop3://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -S --crlf -u billing@example.com:billpass --mail-from billing@example.com --mail-rcpt carol@elsewhere.org -T invoice.eml smtp://127.0.0.1:8080/app.example.com } finally { Stop-Process $server0 }
